import java.util.*; public class ServersScreen extends ScrollableDarkScreen { private final Screen parent; private int scrollY=0; public ServersScreen(Screen parent){super(Component.translatable("multichatwindows.servers.title"));this.parent=parent;} @Override protected void init(){clearWidgets();int cx=width/2,top=54,bottom=height-90,rowH=24;List<String> servers=ConfigManager.listServers();int max=Math.max(0,servers.size()*rowH-(bottom-top));scrollY=Math.max(0,Math.min(scrollY,max));int y=top-scrollY;for(String key:servers){if(y+20>=top&&y<=bottom){addRenderableWidget(new DarkButton(cx-100,y,160,20,Component.translatable("multichatwindows.server.button",Component.literal(key)),()->com.client.multichatwindows.util.MinecraftGuiAccess.setScreen(new TabsScreen(this,key))));addRenderableWidget(new DarkButton(cx+64,y,36,20,Component.translatable("multichatwindows.delete"),()->{ConfigManager.deleteServer(key);init();}));}y+=rowH;}addRenderableWidget(new DarkButton(cx-100,height-54,200,20,Component.translatable("multichatwindows.servers.add"),()->com.client.multichatwindows.util.MinecraftGuiAccess.setScreen(new AddServerScreen(this))));addRenderableWidget(new DarkButton(cx-100,height-28,200,20,Component.translatable("multichatwindows.back"),()->com.client.multichatwindows.util.MinecraftGuiAccess.setScreen(parent)));} @Override protected boolean onScroll(int delta){scrollY+=delta;init();return true;} @Override public void extractRenderState(GuiGraphicsExtractor ctx,int mouseX,int mouseY,float delta){super.extractRenderState(ctx,mouseX,mouseY,delta);com.client.multichatwindows.util.GuiDrawHelper.centered(ctx, font,Component.translatable("multichatwindows.servers.title"),width/2,14,0xFFFFFFFF);} }
